 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var r=main.Combat.Result;bool current=main.State.CurrentFight!=null&&r.key==main.State.CurrentFight.Key&&(main.State.Phase!="Combat"||main.State.CurrentFight.Turn==main.State.Turn);using(var f=Theme.Font(15,true))using(var small=Theme.Font(8.5f)){
  if(!current||r.status!="estimate"){TextRenderer.DrawText(e.Graphics,current?(r.reason??"Calculating…"):(main.State.Duos?"Waiting for all four Duos warbands": "Odds appear when combat starts"),f,new Rectangle(12,10,Width-24,30),Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);return;}
  string label=(main.State.Phase=="Recruit"?"PREVIOUS FIGHT · ":"")+(main.State.Duos?"DUOS TEAM · RECONSTRUCTED ESTIMATE":"EXPERIMENTAL · VISIBLE STATE");TextRenderer.DrawText(e.Graphics,label,small,new Rectangle(10,5,Width-20,19),Theme.Gold,TextFormatFlags.HorizontalCenter);
  int stripWidth=Width-32;int winWidth=(int)(stripWidth*r.win/100),drawWidth=(int)(stripWidth*r.draw/100);using(var wb=new SolidBrush(Theme.Green))using(var db=new SolidBrush(Theme.Muted))using(var lb=new SolidBrush(Color.Salmon)){e.Graphics.FillRectangle(wb,16,55,winWidth,3);e.Graphics.FillRectangle(db,16+winWidth,55,drawWidth,3);e.Graphics.FillRectangle(lb,16+winWidth+drawWidth,55,Math.Max(0,stripWidth-winWidth-drawWidth),3);}var vals=new[]{"WIN "+r.win.ToString("0.0")+"%","DRAW "+r.draw.ToString("0.0")+"%","LOSS "+r.loss.ToString("0.0")+"%"};for(int i=0;i<3;i++)TextRenderer.DrawText(e.Graphics,vals[i],f,new Rectangle(i*Width/3,24,Width/3,32),i==0?Theme.Green:i==2?Color.Salmon:Theme.Ink,TextFormatFlags.HorizontalCenter);
  TextRenderer.DrawText(e.Graphics,r.simulations+" simulations · unknown hand/counters can change odds",small,new Rectangle(6,59,Width-12,22),Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);
 }}
