public class Overlay : Floating {
 readonly Main main;public bool HasPins {get{return !String.IsNullOrEmpty(Pinned)||main.Settings.PinnedCards.Count>0;}}public bool Interactive;public string Pinned="";public readonly Workbench Tools;public readonly HistoryPopup History;public readonly OddsBar Odds;public readonly BuffCounters Buffs;public readonly DuosHistoryPopup DuosHistory;public readonly CardZoom Zoom;readonly Timer hoverTimer=new Timer();Rectangle game;bool active;public readonly HeroChoices HeroPanel;public readonly SideGuide Guide;public readonly SessionPanel SessionBox;
 public Overlay(Main m){main=m;Text="TavernLens Overlay";Opacity=m.Settings.Opacity;Size=new Size(330,265);Zoom=new CardZoom();Tools=new Workbench(m,Zoom);History=new HistoryPopup(m);DuosHistory=new DuosHistoryPopup(m);Odds=new OddsBar(m);Buffs=new BuffCounters(m);HeroPanel=new HeroChoices(m);Guide=new SideGuide(m,this);Controls.Add(Guide);SessionBox=new SessionPanel(m);SetInteractive(true);hoverTimer.Interval=80;hoverTimer.Tick+=(s,e)=>Hover();hoverTimer.Start();ArtCache.Changed+=ImagesChanged;}
 void ImagesChanged(){if(IsDisposed)return;if(InvokeRequired){if(IsHandleCreated)BeginInvoke(new Action(ImagesChanged));return;}Invalidate();Tools.Invalidate(true);History.Invalidate();Zoom.Invalidate();Guide.ImagesChanged();}
 public void SetInteractive(bool value){Interactive=value;PassThrough(!value);SessionBox.PassThrough(!value);if(!value){Tools.Hide();Zoom.Hide();Guide.Preview.Hide();}Invalidate();}
 public bool Follow(IntPtr target,bool eligible){if(target==IntPtr.Zero||Native.IsIconic(target)||!eligible||!main.Settings.OverlayEnabled){active=false;Hide();HeroPanel.Hide();Tools.Hide();History.Hide();DuosHistory.Hide();Odds.Hide();Buffs.Hide();Zoom.Hide();Guide.Preview.Hide();SessionBox.Hide();return false;}game=Native.ClientBounds(target);if(game.Width<400||game.Height<300){active=false;Hide();HeroPanel.Hide();SessionBox.Hide();Guide.Preview.Hide();Tools.Hide();Odds.Hide();Buffs.Hide();History.Hide();DuosHistory.Hide();Zoom.Hide();return false;}active=true;int width=Math.Min(main.Settings.OverlayWidth,game.Width/2);Place(new Rectangle(game.Right-width-12,game.Top+20,width,Guide.Collapsed?54+(HasPins?150:0):Math.Min(900,game.Height-40)));if(main.Scenes.InLobby||main.Previewing)SessionBox.Follow(game);else SessionBox.Hide();Guide.Sync();HeroPanel.Follow(game);if(main.State.Battlegrounds&&!main.State.Complete&&main.Scenes.Scene!="BACON"){Odds.Place(new Rectangle(game.X+game.Width/2-265,game.Bottom-110,530,87));Odds.Invalidate();}else Odds.Hide();Buffs.Follow(game);Tools.RefreshHistory();Invalidate();return true;}
 public void RefreshLayout(){if(!active)return;int width=Math.Min(main.Settings.OverlayWidth,game.Width/2);Place(new Rectangle(game.Right-width-12,game.Top+20,width,Guide.Collapsed?54+(HasPins?150:0):Math.Min(900,game.Height-40)));}
 public static int HoverSlot(Point cursor,Rectangle b){double logicalWidth=b.Height*4.0/3.0;double left=b.Left+(b.Width-logicalWidth)/2.0;double tile=b.Height*0.69/8.0;double top=b.Top+b.Height*0.15;int slot=(int)Math.Floor((cursor.Y-top)/tile);if(slot<0||slot>7)return -1;double x=left+logicalWidth*0.001*(7-slot);return cursor.X>=x&&cursor.X<=x+tile&&cursor.Y>=top?slot:-1;}
 void Hover(){if(!active||!main.State.Battlegrounds||main.State.Complete||main.Scenes.InLobby||main.Scenes.Loading||Tools.Visible){History.Hide();DuosHistory.Hide();return;}if(main.State.Duos){int team=DuosHistoryPopup.TeamAt(Cursor.Position,game);History.Hide();if(team<0){DuosHistory.Hide();return;}DuosHistory.Display(team,game);return;}DuosHistory.Hide();int slot=HoverSlot(Cursor.Position,game);if(slot<0){History.Hide();DuosHistory.Hide();return;}var hero=main.State.Portrait(slot);if(hero==null){History.Hide();DuosHistory.Hide();return;}FightSnapshot f;main.State.LastFights.TryGetValue(hero.N("PLAYER_ID"),out f);History.Display(f,main.Catalog.Name(hero.CardId)+" · not faced yet",game);}
 protected override void Dispose(bool disposing){if(disposing){ArtCache.Changed-=ImagesChanged;hoverTimer.Stop();hoverTimer.Dispose();Tools.Dispose();History.Dispose();DuosHistory.Dispose();Odds.Dispose();Buffs.Dispose();Zoom.Dispose();Guide.Dispose();SessionBox.Dispose();HeroPanel.Dispose();}base.Dispose(disposing);}
}
